<script setup lang="ts">import {useProductDetailPage} from '../../stores/useProductDetailPage';const {prefs,item,images,preview,loading,unavailable,mobilePreferenceStyle,mobileProductName,mobileProductPicture,formatAmount,load}=useProductDetailPage();</script>
